preConditions.sqlCheck:
SELECT COUNT(*) FROM users
WHERE (user_id, username) IN ((35, 'RegistrationOfficer'), (36, 'Nurse'), (37, 'Doctor'),
                              (38, 'LabTechnician'), (39, 'Pharmacist'), (40, 'Cashier'));

SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END FROM person_attribute a
    INNER JOIN person_attribute_type t ON a.person_attribute_type_id = t.person_attribute_type_id
WHERE t.uuid IN ('057e07a8-2170-4422-b257-26e401e3c151', '486da62c-12a8-463c-ada9-4e8f6488075e');

changeSet.sql:
UPDATE person_attribute SET value = '972AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA' WHERE (value = 'sister' OR value = 'brother')
   AND person_attribute_type_id IN (SELECT person_attribute_type_id FROM person_attribute_type WHERE uuid IN ('057e07a8-2170-4422-b257-26e401e3c151', '486da62c-12a8-463c-ada9-4e8f6488075e'));
UPDATE person_attribute SET value = '5618AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA' WHERE value = 'friend'
   AND person_attribute_type_id IN (SELECT person_attribute_type_id FROM person_attribute_type WHERE uuid IN ('057e07a8-2170-4422-b257-26e401e3c151', '486da62c-12a8-463c-ada9-4e8f6488075e'));
UPDATE person_attribute SET value = '1527AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA' WHERE (value = 'mother' OR value = 'father')
   AND person_attribute_type_id IN (SELECT person_attribute_type_id FROM person_attribute_type WHERE uuid IN ('057e07a8-2170-4422-b257-26e401e3c151', '486da62c-12a8-463c-ada9-4e8f6488075e'));
DELETE FROM person_attribute WHERE value = 'test'
   AND person_attribute_type_id IN (SELECT person_attribute_type_id FROM person_attribute_type WHERE uuid IN ('057e07a8-2170-4422-b257-26e401e3c151', '486da62c-12a8-463c-ada9-4e8f6488075e'));

INSERT INTO cashier_payment_mode (name, creator, date_created, uuid)
SELECT 'Insured Cost', 1, NOW(), '94bd1d63-fe27-48a0-9a1b-d536c0ab3944'
WHERE NOT EXISTS (
    SELECT 1 FROM cashier_payment_mode WHERE uuid = '94bd1d63-fe27-48a0-9a1b-d536c0ab3944'
);

INSERT INTO cashier_payment_mode (name, creator, date_created, uuid)
SELECT 'Non-Insured Cost', 1, NOW(), 'fcf90cf7-7852-4bd5-a8b5-32f2ba8806ec'
WHERE NOT EXISTS (
    SELECT 1 FROM cashier_payment_mode WHERE uuid = 'fcf90cf7-7852-4bd5-a8b5-32f2ba8806ec'
);
